import SwiftUI

/// Semantic colour tokens of the Welcome poster (`Assets.xcassets/Welcome`, Any + Dark, generated by
/// `Tools/make_onboarding_colors.py`). Light is the terracotta poster, dark is charcoal.
enum WelcomeColor {
    static let bgTop = Color("welcome.bgTop")
    static let bgMid = Color("welcome.bgMid")
    static let bgBottom = Color("welcome.bgBottom")
    static let glow = Color("welcome.glow")
    static let textPrimary = Color("welcome.textPrimary")
    /// Star and sparkles.
    static let highlight = Color("welcome.highlight")
    static let textSecondary = Color("welcome.textSecondary")
    static let textTertiary = Color("welcome.textTertiary")
    static let ctaFill = Color("welcome.ctaFill")
    static let ctaLabel = Color("welcome.ctaLabel")
    static let ctaShadow = Color("welcome.ctaShadow")
    static let stampShadow = Color("welcome.stampShadow")
    static let stampShadowHero = Color("welcome.stampShadowHero")
    static let postmark = Color("welcome.postmark")
    static let progressOn = Color("welcome.progressOn")
    static let progressOff = Color("welcome.progressOff")
    static let wordWorldFill = Color("welcome.wordWorldFill")
    static let wordWorldText = Color("welcome.wordWorldText")
    static let wordStampFill = Color("welcome.wordStampFill")
    static let wordStampText = Color("welcome.wordStampText")

    /// Asset names of every token, for the resolution test.
    nonisolated static let assetNames = [
        "bgTop", "bgMid", "bgBottom", "glow", "textPrimary", "highlight", "textSecondary", "textTertiary", "ctaFill",
        "ctaLabel", "ctaShadow", "stampShadow", "stampShadowHero", "postmark", "progressOn", "progressOff",
        "wordWorldFill", "wordWorldText", "wordStampFill", "wordStampText",
    ].map { "welcome." + $0 }
}
